import {canShowcase,updateDraft,exampleEntries,localEntries,findEntry,filterEntries,agentDraftPrompt} from './workspace.mjs';
import {createLocalCover,validCover} from './media.mjs';
import {DEFAULT_FORM,SAMPLES,SCHEMA,MAX_MANIFEST_LENGTH,cleanForm,validateForm,economics,formatUnits,previewQuote,manifestFor,importManifest,agentBrief,sampleForm} from './model.mjs';
const $=id=>document.getElementById(id),app=$('app'),dialog=$('dialog'),KEY='echo.launch.drafts.v1',LANG='echo.launch.language.v1',VIEW='echo.launch.view.v1';
let pendingScroll='';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageError=false;function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{storageError=true;return fallback;}}
let drafts=read(KEY,[]);if(!Array.isArray(drafts))drafts=[];drafts=drafts.filter(d=>d&&typeof d.id==='string'&&d.form).map(d=>({...d,form:cleanForm(d.form)}));
const restoredDraft=location.hash==='#/create'?drafts[0]:null;
const state={lang:read(LANG,'zh')==='en'?'en':'zh',search:'',phase:'all',category:'all',sort:'featured',catalog:'published',view:read(VIEW,'grid')==='list'?'list':'grid',draftFilter:'all',step:restoredDraft?draftStep(restoredDraft):1,errors:{},form:restoredDraft?{...restoredDraft.form}:{...DEFAULT_FORM},id:restoredDraft?.id||null,confirmed:false,tab:'overview',quantity:'1'};
const t=(zh,en)=>state.lang==='zh'?zh:en,n=x=>Number(x).toLocaleString(state.lang==='zh'?'zh-CN':'en-US'),u=x=>{const [i,f]=formatUnits(x).split('.');return i.replace(/\B(?=(\d{3})+(?!\d))/g,',')+(f?'.'+f:'')},uid=()=>`draft-${crypto.randomUUID?.()||Date.now().toString(36)}`;
const category=k=>({tools:t('Agent 工具','Agent tools'),creative:t('创作与文化','Creative'),community:t('社区应用','Community')})[k]||k;
const phase=k=>({raising:t('募集中 · 示例','Raising · example'),preparing:t('筹备中 · 示例','Preparing · example'),opened:t('已开盘 · 示例','Opened · example'),draft:t('本地草稿','Local draft')})[k];
const formLabels=()=>({cover:t('项目封面','Project cover'),name:t('项目名称','Project name'),symbol:t('代币符号','Token symbol'),tagline:t('一句话介绍','One-line introduction'),description:t('项目说明','Project description'),website:t('项目官网','Project website'),x:'X',telegram:'Telegram',category:t('项目分类','Category'),shares:t('发行总份数','Total shares'),allocation:t('每份代币数量','Tokens per share'),price:t('固定单价','Fixed share price'),limit:t('每个身份累计上限','Lifetime cap per identity'),maxTx:t('单笔份数上限','Shares per transaction'),liquidity:t('募集资金入池比例','Raise allocated to liquidity'),days:t('募集期限','Raise duration')});
const messages=()=>({x:t('请填写 https://x.com/ 或 https://twitter.com/ 链接。','Use an https://x.com/ or https://twitter.com/ URL.'),telegram:t('请填写 https://t.me/ 或 https://telegram.me/ 链接。','Use an https://t.me/ or https://telegram.me/ URL.'),cover:t('请使用有效的 HTTPS 图片地址，或重新选择 JPG、PNG、WebP 封面。','Use a valid HTTPS image URL, or choose a JPG, PNG or WebP cover again.'),name:t('请输入 2–32 字的项目名称。','Use 2–32 characters.'),symbol:t('使用 2–10 位大写字母或数字，首位为字母。','Use 2–10 uppercase letters/digits, starting with a letter.'),tagline:t('请填写 6–100 字的简短介绍。','Use 6–100 characters.'),description:t('请填写 20–2,000 字的项目说明。','Use 20–2,000 characters.'),website:t('请输入完整 HTTPS 链接，不含登录凭据。','Enter an HTTPS URL with no login credentials.'),category:t('请选择一个项目分类。','Choose a category.'),shares:t('请输入 1–10,000,000 的整数。','Enter a whole number from 1 to 10,000,000.'),allocation:t('请输入 1–1,000,000,000 的整数。','Enter a whole number from 1 to 1,000,000,000.'),limit:t('请输入 1–10,000 的整数。','Enter a whole number from 1 to 10,000.'),maxTx:t('请输入 1–100 的整数。','Enter a whole number from 1 to 100.'),days:t('请输入 1–30 天的整数。','Enter a whole number from 1 to 30 days.'),price:t('请输入大于 0、最多 100 BNB 的十进制金额，最多 18 位小数。','Enter a decimal above 0 and at most 100 BNB, up to 18 decimal places.'),liquidity:t('请输入 50–100 的整数百分比。','Enter a whole percentage from 50 to 100.'),limitSupply:t('身份额度不能超过发行总份数。','Identity cap cannot exceed total shares.'),maxTxLimit:t('单笔上限不能超过身份累计上限。','Transaction cap cannot exceed the identity cap.')});
function toast(text,bad=false){const e=$('toast');e.textContent=text;e.classList.toggle('error-toast',bad);e.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.hidden=true,4200);}
function persist(options={}){
 if(!state.id)state.id=uid();
 const previous=drafts.find(d=>d.id===state.id);
 let record;
 try{record=updateDraft(previous,state.form,{id:state.id,step:state.step,...options});}catch{return false;}
 const next=[record,...drafts.filter(d=>d.id!==record.id)];
 try{localStorage.setItem(KEY,JSON.stringify(next));drafts=next;storageError=false;if($('draft-count'))$('draft-count').textContent='· '+drafts.length;return true;}catch{storageError=true;return false;}
}

function saveState(){const el=$('save-state');if(el)el.textContent=storageError?t('最新变更尚未保存。请导出 JSON，避免丢失。','Latest changes are not saved. Export JSON to keep them.'):t('已保存到当前浏览器 · 不会上传','Saved in this browser · never uploaded');}

function setHash(value,section=''){pendingScroll=section;if(location.hash===value){render();finishNavigation();}else location.hash=value;}

function newDraft(){state.form={...DEFAULT_FORM};state.id=null;state.step=1;state.errors={};state.confirmed=false;setHash('#/create');}
function header(route){
 return `<header class="header"><div class="wrap header-row"><a class="brand" href="#/projects" aria-label="ECHO Launch"><img src="../assets/echo-sculpture-mark.webp" alt=""><div><div class="brand-name">ECHO</div><small>LAUNCH</small></div></a><nav class="nav" aria-label="${t('平台导航','Platform navigation')}"><a href="#/projects" class="${['projects','project'].includes(route)?'active':''}">${t('项目市场','Explore')}</a><a href="#/create" class="${route==='create'?'active':''}">${t('发起项目','Create')}</a><a href="#/drafts" class="${route==='drafts'?'active':''}">${t('我的项目','My projects')} <span id="draft-count">${drafts.length?'· '+drafts.length:''}</span></a><a href="#/agent" class="${route==='agent'?'active':''}">${t('Agent 文档','For agents')} ↗</a></nav><div class="header-actions"><button class="language" data-action="language" aria-label="${t('切换到 English','Switch to 中文')}">${state.lang==='zh'?'<b>中</b> / EN':'中 / <b>EN</b>'}</button><button class="button primary small" data-action="new">${t('发起项目','Create a launch')} ↗</button></div></div></header><div class="notice"><div class="wrap"><span><b>${t('本地体验版','LOCAL PREVIEW')}</b> · ${t('草稿和展示仅在当前浏览器；尚未接入真实发行。','Drafts and showcases stay in this browser. Live issuance is not connected.')}</span><a href="../#mint">${t('ECHO 现有 Mint','Existing ECHO Mint')} ↗</a></div></div>${storageError?`<div class="storage-warning" role="status">${t('浏览器未能保存最新变更，请导出 JSON。','Latest changes could not be saved. Export JSON to keep them.')}</div>`:''}`;
}

function footer(){return `<footer class="footer"><div class="wrap"><div class="footer-row"><a class="brand-name" href="#/projects">ECHO</a><div class="footer-links"><a href="#/agent">${t('Agent 使用指南','Agent guide')}</a><a href="./agent-guide.md" target="_blank" rel="noopener">agent-guide.md ↗</a><a href="../">${t('ECHO 官网','ECHO home')} ↗</a><button class="text-button" data-action="help">${t('如何体验','How to explore')}</button></div><span>BNB CHAIN / 56 · FRONT-END PREVIEW</span></div><p>${t('示例项目不代表已发行资产或官方推荐。本预览不连接钱包、不请求签名；新发行模板不改变 ECHO 现有 Mint 的任何规则。','Illustrative projects are not issued assets or endorsements. This preview connects no wallet and requests no signature. The new template does not change existing ECHO Mint rules.')}</p></div></footer>`;}
function hero(){
 return `<section class="hero market-hero"><div class="wrap hero-grid"><div class="hero-copy"><div class="eyebrow">ECHO LAUNCH / AGENT-NATIVE ISSUANCE</div><h1>${t('发现项目。<i>发起你的下一步。</i>','Discover projects. <i>Launch your own.</i>')}</h1><p>${t('从项目封面，到清楚的发行规则，再交给你的 Agent。','Discover the project, review the terms, then hand it to your Agent.')}</p><div class="hero-buttons"><button class="button primary" data-action="new">${t('创建发行方案','Create a launch')} ↗</button><button class="text-button" data-action="agent-create">${t('让 Agent 帮我填写','Prepare with my Agent')} ↗</button></div></div><div class="hero-art" aria-hidden="true"><img src="../assets/echo-sculpture-v4.webp" alt=""></div></div><div class="wrap hero-foot"><span>BNB CHAIN / 56</span><span>AGENT-ONLY</span><span>${t('固定价格 · 满额开盘模板','FIXED PRICE · FULL-RAISE TEMPLATE')}</span></div></section>`;
}

function card(entry){
 const f=entry.form,local=entry.origin==='local',pct=local?null:Math.floor(entry.filled/Number(f.shares)*100);
 return `<article class="project-card"><a class="card-link" href="#/project/${escape(entry.id)}" aria-label="${escape(f.name)} · ${t('查看项目详情','View project details')}"><div class="card-cover">${entry.artwork?`<img class="project-cover-image" src="${escape(entry.artwork)}" alt="${escape(f.name)} · ${t('项目封面','project cover')}" loading="lazy" referrerpolicy="no-referrer"><span class="cover-image-error" hidden>${t('封面暂不可用','Cover unavailable')}</span>`:`<span class="cover-placeholder" aria-hidden="true">＋</span>`}<span class="cover-demo">${local?t('本地展示','LOCAL SHOWCASE'):t('演示项目','EXAMPLE')}</span><span class="cover-phase">${local?t('尚未发行','NOT ISSUED'):({raising:t('募集中','Raising'),preparing:t('筹备中','Preparing'),opened:t('已开盘','Opened')})[entry.phase]}</span></div><div class="card-copy"><div class="card-identity"><h3>${escape(f.name)}</h3><span>$${escape(f.symbol)}</span></div><p class="tagline">${escape(f.tagline)}</p><div class="card-rule"><strong>${escape(f.price)} <small>BNB</small></strong><small>${t('每份','per share')}</small></div><div class="progress" ${local?'aria-hidden="true"':`role="progressbar" aria-label="${t('示例募集进度','Illustrative raise progress')}" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100"`}><span style="width:${pct??0}%"></span></div><div class="progress-label"><span>${local?t('募集尚未开始','Raise not started'):t('演示进度','Example progress')}</span><span>${local?'—':pct+'%'}</span></div><div class="card-bottom"><span>${category(f.category)}</span><span>${t('查看详情','View details')} ↗</span></div></div></a></article>`;
}

function matching(){
 const entries=state.catalog==='examples'?exampleEntries(state.lang):state.catalog==='local'?localEntries(drafts):[];
 return filterEntries(entries,state);
}

function projectResults(){
 const entries=matching();
 if(entries.length)return entries.map(card).join('');
 if(state.search||state.phase!=='all'||state.category!=='all')return `<div class="empty"><h3>${t('没有匹配的项目','No matching projects')}</h3><p>${t('尝试其他关键词，或清除筛选条件。','Try another search or clear the filters.')}</p><button class="button" data-action="clear-filters">${t('清除筛选','Clear filters')}</button></div>`;
 return `<div class="empty"><h3>${t('你的本地项目，从这里开始。','Your local launch starts here.')}</h3><p>${t('完成发行方案并审阅后，点击“加入本地展示”，就能在这里查看自己的项目卡片。','Complete and review a launch draft, then choose Add to local showcase to see its card here.')}</p><button class="button primary" data-action="new">${t('创建发行方案','Create a launch')} ↗</button></div>`;
}

function market(){
 const examples=state.catalog==='examples',local=state.catalog==='local',mine=localEntries(drafts).length;
 const labels={published:t('项目市场','Published'),local:t('我的本地展示','My local showcase'),examples:t('演示项目','Examples')};
 const phases=local?['all','draft']:['all','preparing','raising','opened'];
 return `${hero()}<main id="main" class="wrap section market-section"><section id="projects"><div class="section-heading"><div><div class="eyebrow">THE PROJECT MARKET</div><h2>${t('从一张封面，发现一个项目。','Discover the project behind the cover.')}</h2><p>${t('浏览项目、读懂规则，再选择参与方式。','Explore the project, understand the terms and review participation.')}</p></div><button class="text-button" data-action="help">${t('如何体验','How it works')} ↗</button></div><div class="catalog-switch" aria-label="${t('项目目录','Project catalog')}">${['published','local','examples'].map(k=>`<button data-catalog="${k}" aria-pressed="${state.catalog===k}">${labels[k]} <span>${k==='published'?0:k==='local'?mine:3}</span></button>`).join('')}</div>${state.catalog==='published'?`<div class="market-empty"><div class="empty-cover-art" aria-hidden="true"><span></span><span></span><span></span></div><div><div class="eyebrow">READY FOR THE FIRST LAUNCH</div><h3>${t('还没有已发布的项目','No published projects yet')}</h3><p>${t('正式发行接入后，这里会展示创建者的项目封面和已核验的发行状态。现在可以先创建方案，体验本地展示与 Agent 交接。','Once live issuance is connected, this market will show creator projects and verified launch states. Prepare a draft now to try local showcases and Agent handoff.')}</p><div class="empty-actions"><button class="button primary" data-action="new">${t('发起我的项目','Create my project')} ↗</button><button class="text-button" data-catalog="examples">${t('先看看演示项目','Explore examples first')} ↗</button>${mine?`<button class="text-button" data-catalog="local">${t('查看我的本地展示','My local showcase')} ↗</button>`:''}</div><small>${t('本地草稿与本地展示不会自动变成公开发行。','Local drafts and showcases are never public launches.')}</small></div></div>`:`<div class="catalog-explanation"><b>${examples?t('仅为流程演示，项目和进度均为虚构','Fictional projects and progress for exploring the flow'):t('仅当前浏览器可见，尚未发行','Visible in this browser only · not issued')}</b><p>${examples?t('点击项目查看详情；也可以创建自己的方案，加入本地展示。','Open a project for details, or create your own draft and add a local showcase.'):t('这里展示你已审阅的本地方案。无真实合约、募集或成交数据。修改方案后需重新审阅。','These are your reviewed local briefs, with no live contracts, contributions or trades. Review again after making changes.')}</p></div><div class="toolbar"><div class="search"><span aria-hidden="true">⌕</span><input id="project-search" type="search" value="${escape(state.search)}" placeholder="${t('搜索名称、符号或简介','Search name, symbol or introduction')}" aria-label="${t('搜索项目','Search projects')}"></div><select id="category-filter" aria-label="${t('项目分类筛选','Filter by category')}"><option value="all">${t('所有分类','All categories')}</option>${['tools','creative','community'].map(k=>`<option value="${k}" ${state.category===k?'selected':''}>${category(k)}</option>`).join('')}</select><select id="sort-projects" aria-label="${t('项目排序','Sort projects')}">${[['featured',t('默认顺序','Default order')],['price',t('单价从低到高','Lowest share price')],['name',t('名称排序','Project name')],...(!local?[['progress',t('示例进度优先','Example progress')]]:[])].map(([v,l])=>`<option value="${v}" ${state.sort===v?'selected':''}>${l}</option>`).join('')}</select><div class="view-toggle" aria-label="${t('项目展示方式','Project view')}"><button data-view="grid" aria-label="${t('图片网格','Cover grid')}" aria-pressed="${state.view==='grid'}">▦</button><button data-view="list" aria-label="${t('紧凑列表','Compact list')}" aria-pressed="${state.view==='list'}">☰</button></div></div><div class="filter-row"><div class="filters" aria-label="${t('发行阶段','Launch phase')}">${phases.map(k=>`<button class="chip" data-phase="${k}" aria-pressed="${state.phase===k}">${({all:t('全部','All'),preparing:t('筹备中','Preparing'),raising:t('募集中','Raising'),opened:t('已开盘','Opened'),draft:t('尚未发行','Not issued')})[k]}</button>`).join('')}</div><span class="result-count" id="result-count" aria-live="polite">${matching().length} ${t('个项目','PROJECTS')}</span></div><div class="project-grid ${state.view==='list'?'market-list':''}" id="project-results">${projectResults()}</div>`}</section><div class="market-flow"><div><span>01</span><h3>${t('发现项目','Discover')}</h3><p>${t('先看封面、介绍与发行阶段。','Start with the cover, introduction and phase.')}</p></div><div><span>02</span><h3>${t('看清规则','Review')}</h3><p>${t('核对价格、额度、资金用途和退款条件。','Check price, caps, funding and refunds.')}</p></div><div><span>03</span><h3>${t('交给 Agent','Hand off')}</h3><p>${t('把完整方案交给 Agent，保留用户确认。','Give your Agent the full brief and keep user consent.')}</p></div></div></main>`;
}

function rules(f){return `<ol class="rule-list"><li><b>${t('参与资格与额度','Eligibility and limits')}</b>${t(`官方 .ai Agent 身份；每个身份累计最多 ${n(f.limit)} 份，单笔最多 ${n(f.maxTx)} 份。预览不核验真实资格。`,`Official .ai Agent identity; up to ${n(f.limit)} lifetime shares per identity and ${n(f.maxTx)} per transaction. Live eligibility is not verified here.`)}</li><li><b>${t('固定价格与直接分配','Fixed price and allocation')}</b>${t(`每份 ${f.price} BNB，对应 ${n(f.allocation)} ${escape(f.symbol)}；本模板没有首免或邀请奖励，网络 Gas 另计。`,`${f.price} BNB per share for ${n(f.allocation)} ${escape(f.symbol)}. No free allocation or referral rewards in this template. Network gas is separate.`)}</li><li><b>${t('满额开盘','Full-raise opening')}</b>${t(`正式发行开始起 ${f.days} 天内募满 ${n(f.shares)} 份，才满足建池条件；不设提前开盘。`,`The raise must fill ${n(f.shares)} shares within ${f.days} days of its official start. No early opening.`)}</li><li><b>${t('资金与代币分配','Funding and token allocation')}</b>${t(`满额后，${f.liquidity}% 募集资金与对应流动性代币建池，${100-Number(f.liquidity)}% 分配给项目方。LP 约定销毁。平台费未设置。`,`After a full raise, ${f.liquidity}% of funds and matching liquidity tokens seed the pool; ${100-Number(f.liquidity)}% goes to the project. LP is specified to be burned. No platform fee is configured.`)}</li><li><b>${t('未满额的处理','If the raise does not fill')}</b>${t('募集到期且未满额时，参与者可主动申请退回其 Mint 付款，Gas 不退；满额开盘后不适用此退款。募集期间资金应由发行合约按规则保管。','After expiry without a full raise, participants may request their Mint payment back; gas is not refunded. This refund does not apply after full-raise opening. Funds should remain governed by the issuance contract during the raise.')}</li></ol>`;}
function projectFor(id){const entry=findEntry(id,drafts,state.lang);if(!entry)return null;return{entry,f:entry.form,local:entry.origin==='local',p:{...entry.form,...entry,tone:'gold',mark:entry.form.symbol.slice(0,1)}};}

function quotePanel(f,p){
 const done=p.phase==='opened',local=p.origin==='local',cap=Math.min(Number(f.limit),Number(f.maxTx));
 return `<aside class="participation panel"><div class="panel-kicker"><span>FIXED-PRICE / BNB</span><span>${t('方案预览','DRAFT PREVIEW')}</span></div><div class="big-price">${escape(f.price)}<small>BNB / ${t('份','share')}</small></div><div class="kv"><span>${t('每份代币','Tokens per share')}</span><b>${n(f.allocation)} ${escape(f.symbol)}</b></div><div class="quote-status"><span class="status-dot"></span>${local?t('尚未发行 · 无链上募集数据','Not issued · no on-chain raise data'):done?t('募集完成状态的演示','Illustrative completed phase'):t('当前为虚构项目演示','Fictional project example')}</div>${!local?`<div class="progress"><span style="width:${Math.floor(p.filled/Number(f.shares)*100)}%"></span></div><div class="progress-label"><span>${n(p.filled)} / ${n(f.shares)} ${t('演示份额','example shares')}</span><span>${Math.floor(p.filled/Number(f.shares)*100)}%</span></div>`:''}<div class="divider"></div>${done?`<p class="body-copy">${t('本示例用于查看完成阶段的资料，不提供交易或追加 Mint。','This example shows the completed phase, with no trading or additional Mint.')}</p>`:`<label for="quote-quantity">${t('计算参与份数','Calculate shares')}</label><div class="quantity"><button data-action="minus" aria-label="${t('减少份数','Decrease shares')}">−</button><input id="quote-quantity" inputmode="numeric" value="${escape(state.quantity)}" aria-label="${t('预览份数','Preview shares')}" aria-describedby="quote-limit quote-error"><button data-action="plus" aria-label="${t('增加份数','Increase shares')}">+</button></div><p class="mini-note" id="quote-limit">${t(`单笔最多 ${cap} 份；身份累计上限 ${f.limit} 份。`,`Up to ${cap} shares per transaction; ${f.limit} lifetime shares per identity.`)}</p><div id="quote-error" class="error" role="status"></div><div class="amount-total"><span>${t('方案付款金额','Illustrative payment')}</span><strong id="quote-payment">—</strong></div><div class="kv"><span>${t('对应代币','Token allocation')}</span><b id="quote-tokens">—</b></div><div class="kv"><span>${t('网络 Gas','Network gas')}</span><b>${t('另计 · 尚未估算','Separate · not estimated')}</b></div>`}<button class="button primary full" data-action="participate" style="margin-top:22px">${done?t('交给 Agent 审阅资料','Review with my Agent'):t('生成 Agent 参与方案','Prepare Agent participation brief')} ↗</button><button class="text-button full" data-action="export-project">${t('下载完整项目 JSON','Download full project JSON')} ↓</button><p class="mini-note">${t('当前只生成审阅方案。不会连接钱包、请求签名或提交 Mint。','Creates a review brief only. No wallet connection, signing or Mint.')}</p><div class="quote-identity"><span>AGENT-ONLY</span><p>${t('正式参与要求官方 .ai Agent 身份；本地预览不核验身份或实际额度。','Live participation requires an official .ai Agent identity. This preview verifies neither identity nor live quota.')}</p></div></aside>`;
}

function detailContent(f,p){
 const m=economics(f),local=p.origin==='local';
 const links=[['website',t('项目官网','Website')],['x','X'],['telegram','Telegram']].filter(([key])=>f[key]);
 if(state.tab==='rules')return `<section class="panel detail-section"><div class="eyebrow">FIXED-PRICE / 01</div><h2>${t('完整发行规则','Complete launch terms')}</h2><p class="mini-note">${t('这是待确认的新项目模板，不改变 ECHO 原有 Mint 规则。','Proposed terms for a new project, separate from existing ECHO Mint rules.')}</p>${rules(f)}<div class="rule-facts"><div><span>${t('网络','Network')}</span><b>BNB Chain · 56</b></div><div><span>${t('开放条件','Opening condition')}</span><b>${t('募集满额','Full raise only')}</b></div><div><span>${t('募集起点','Raise start')}</span><b>${t('正式开始时间尚未设置','Official start not set')}</b></div><div><span>${t('交易税 / 平台费','Trading tax / platform fee')}</span><b>${t('尚未配置，需正式确认','Not configured · confirmation needed')}</b></div></div></section>`;
 if(state.tab==='participation')return `<section class="panel detail-section"><div class="eyebrow">PARTICIPATION / AGENT-ONLY</div><h2>${t('先算清楚，再交给 Agent。','Understand the numbers before handoff.')}</h2><ol class="journey-list"><li><span>01</span><div><h3>${t('核对项目与身份','Check project and identity')}</h3><p>${t('确认项目名称、符号、发行规则与官方 .ai 身份要求。','Review the project name, symbol, terms and official .ai identity requirement.')}</p></div></li><li><span>02</span><div><h3>${t('选择份数，查看完整费用','Choose shares and review costs')}</h3><p>${t('方案付款与网络 Gas 分开。这里的计算不会核验实际可用额度。','Draft payment and network gas are separate. This calculator does not verify live available quota.')}</p></div></li><li><span>03</span><div><h3>${t('复制给自己的 Agent','Copy to your own Agent')}</h3><p>${t('方案包含完整参数、份数和停止条件。也可下载 JSON 一并审阅。','The brief includes all parameters, your quantity and stop conditions. Download JSON for a complete review.')}</p></div></li><li><span>04</span><div><h3>${t('保留用户确认','Keep user confirmation')}</h3><p>${t('真实合约接入前只审阅。未来需先读取官方配置、链上状态和实时费用，再单独确认执行。','Review only until live contracts exist. A future integration must read official configuration, on-chain state and current costs before separate execution consent.')}</p></div></li></ol><button class="button primary" data-action="participate">${t('生成 Agent 参与方案','Prepare Agent participation brief')} ↗</button><details class="participation-faq"><summary>${t('现在会产生交易吗？','Will this create a transaction?')}</summary><p>${t('不会。本地前端没有接入发行合约，不会生成交易哈希或收款回执。','No. No issuance contract is connected, and no transaction hash or payment receipt is generated.')}</p></details></section>`;
 if(state.tab==='agent')return `<section class="panel detail-section"><div class="eyebrow">MACHINE-READABLE / HUMAN-REVIEWED</div><h2>${t('Agent 所需的信息，放在一起。','Everything your Agent needs, together.')}</h2><p class="body-copy">${t('复制指令即可交接规则与费用算例；JSON 保留全部字段与本地封面。','Copy the brief to hand over the rules and cost example. JSON retains all fields and the local cover.')}</p><div class="agent-readiness"><div><b>BNB Chain / 56</b><span>${t('目标网络已注明','Target network specified')}</span></div><div><b>${t('合约未接入','Contracts not connected')}</b><span>executionReady = false</span></div><div><b>${t('身份尚未核验','Identity not verified')}</b><span>${t('不代表真实参与资格','No live eligibility claim')}</span></div><div><b>${t('Gas 尚未估算','Gas not estimated')}</b><span>${t('执行前需另行核验','Must be verified before execution')}</span></div></div><div class="handoff-actions"><button class="button primary" data-action="participate">${t('查看并复制指令','Review and copy brief')} ↗</button><button class="button" data-action="export-project">${t('下载项目 JSON','Download project JSON')} ↓</button></div><p class="agent-reference-links"><a class="text-button" href="./agent-guide.md" target="_blank" rel="noopener">Agent guide ↗</a><a class="text-button" href="./schema.json" target="_blank" rel="noopener">JSON schema ↗</a></p><details><summary>${t('展开完整配置','Expand full configuration')}</summary><pre class="code-box">${escape(JSON.stringify({...manifestFor({...f,cover:f.cover.startsWith('data:')?'':f.cover},p.id),...(f.cover.startsWith('data:')?{assets:{cover:'Embedded in downloaded JSON; omitted here for readability.'}}:{})},null,2))}</pre></details></section>`;
 return `<section class="panel detail-section"><div class="eyebrow">ABOUT THE PROJECT</div><h2>${t('项目介绍','About this project')}</h2><p class="body-copy project-description">${escape(f.description)}</p>${links.length?`<div class="project-links">${links.map(([key,label])=>`<a class="button small" href="${escape(f[key])}" target="_blank" rel="noopener noreferrer nofollow">${label} ↗</a>`).join('')}<small>${t('链接由项目提供，尚未核验。','Project-provided links · not verified.')}</small></div>`:''}<div class="facts"><div class="fact"><span>${t('募集目标','Raise target')}</span><strong>${u(m.raisedWei)} BNB</strong></div><div class="fact"><span>${t('发行份数','Total shares')}</span><strong>${n(f.shares)}</strong></div><div class="fact"><span>${t('总供应量','Total supply')}</span><strong>${u(m.totalSupplyWei)} ${escape(f.symbol)}</strong></div><div class="fact"><span>${t('正式开始后的期限','Duration after official start')}</span><strong>${f.days} ${t('天','days')}</strong></div></div><h3>${t('募集资金与代币分配','Funding and token allocation')}</h3><div class="fund-split"><span style="width:${f.liquidity}%">${f.liquidity}%</span><span style="width:${100-Number(f.liquidity)}%">${Number(f.liquidity)<100?(100-Number(f.liquidity))+'%':''}</span></div><div class="kv"><span>${t('建池资金','Liquidity funds')}</span><b>${u(m.liquidityWei)} BNB</b></div><div class="kv"><span>${t('项目方资金','Project funds')}</span><b>${u(m.projectWei)} BNB</b></div><div class="kv"><span>${t('参与者代币','Participant tokens')}</span><b>${u(m.soldWei)} ${escape(f.symbol)}</b></div><div class="kv"><span>${t('建池代币','Liquidity tokens')}</span><b>${u(m.poolTokensWei)} ${escape(f.symbol)}</b></div><p class="mini-note">${t('分配仅为方案核算。建池比例不是可成交价格或收益承诺。','Draft allocation only. Pool ratios are not executable prices or return promises.')}</p></section><section class="panel detail-section"><h2>${t('参与前，先确认这三件事。','Three things to review first.')}</h2><div class="detail-checks"><p>✓ ${t('官方 .ai Agent 身份要求','Official .ai Agent identity requirement')}</p><p>✓ ${t('单笔与累计额度分别计算','Separate transaction and lifetime caps')}</p><p>✓ ${t('满额开盘与未满额退款条件','Full-raise opening and unfilled-raise refund terms')}</p></div><button class="text-button" data-tab="rules">${t('查看完整规则','Read all terms')} ↗</button></section>`;
}

function flow(compact=false){return `<div class="flow" ${compact?'style="margin:0;padding:0;border:0"':''}><div><span>01</span><h3>${t('先看规则','Read the rules')}</h3><p>${t('看清价格、份额、资金用途与退款条件。','Check price, limits, funding and refunds.')}</p></div><div><span>02</span><h3>${t('交给 Agent 审阅','Review with your Agent')}</h3><p>${t('复制完整指令，先审核方案与缺失配置。','Copy the complete brief and review missing configuration.')}</p></div><div><span>03</span><h3>${t('保留用户确认','Keep user consent')}</h3><p>${t('真实发行接入前停止，不以草稿授权交易。','Stop before live integration. A draft never authorizes a transaction.')}</p></div></div>`;}
function projectPage(id){
 const result=projectFor(id);
 if(!result)return `<main id="main" class="wrap section"><div class="empty"><h1>${t('没有找到这份项目','Project not found')}</h1><p>${t('本地项目只在保存它的浏览器可见。换设备时，请先导入方案 JSON。','Local projects are visible only in the browser that saved them. Import the JSON when switching devices.')}</p><button class="button" data-action="import">${t('导入方案','Import draft')} ↥</button> <a class="button primary" href="#/projects">${t('返回项目市场','Back to projects')}</a></div></main>`;
 const{f,p,entry}=result,local=entry.origin==='local',back=local?'local':'examples',done=p.phase==='opened';
 const tabLabels={overview:t('项目介绍','Overview'),rules:t('发行规则','Launch terms'),participation:t('参与步骤','Participation'),agent:t('Agent 资料','Agent resources')};
 return `<main id="main" class="wrap detail-page"><div class="breadcrumb"><a href="#/projects/${back}">← ${local?t('我的本地展示','My local showcase'):t('演示项目','Examples')}</a><span>/</span><span>${escape(f.name)}</span></div><div class="detail-head"><div class="detail-title"><div class="eyebrow">${local?t('LOCAL PROJECT / 尚未发行','LOCAL PROJECT / NOT ISSUED'):t('ILLUSTRATIVE PROJECT / 虚构示例','ILLUSTRATIVE PROJECT')}</div><h1>${escape(f.name)}</h1><p>$${escape(f.symbol)} · ${category(f.category)} · BNB CHAIN / 56</p></div><div class="detail-header-actions"><span class="badge draft">${local?(entry.listed?t('本地展示','Local showcase'):t('本地草稿','Local draft')):phase(p.phase)}</span>${local?`<button class="text-button" data-edit="${escape(p.id)}">${t('编辑项目','Edit project')} ↗</button>`:''}</div></div><div class="detail-grid"><div class="detail-main"><div class="detail-project-cover">${entry.artwork?`<img class="project-cover-image" src="${escape(entry.artwork)}" alt="${escape(f.name)} · ${t('项目封面','project cover')}" referrerpolicy="no-referrer"><span class="cover-image-error" hidden>${t('封面暂不可用','Cover unavailable')}</span>`:`<div class="detail-cover-placeholder"><img src="../assets/echo-sculpture-v4.webp" alt=""><span>${t('项目尚未设置封面','Project cover not set')}</span></div>`}<span class="detail-cover-label">${local?'LOCAL PREVIEW':'ILLUSTRATIVE EXAMPLE'}</span></div><nav class="detail-tabs" role="tablist" aria-label="${t('项目资料','Project information')}">${Object.entries(tabLabels).map(([k,label])=>`<button role="tab" id="detail-tab-${k}" aria-controls="detail-panel" aria-selected="${state.tab===k}" tabindex="${state.tab===k?0:-1}" data-tab="${k}">${label}</button>`).join('')}</nav><div role="tabpanel" id="detail-panel" aria-labelledby="detail-tab-${state.tab}">${detailContent(f,p)}</div></div>${quotePanel(f,p)}</div><p class="detail-disclosure">${local?t('本地展示不代表公开上架、合约部署或真实发行。','A local showcase is not a public listing, contract deployment or live issuance.'):t('示例名称、封面与进度为虚构资料，不代表真实项目或推荐。','Example names, covers and progress are fictional, not real projects or endorsements.')}</p></main>${!done?`<div class="mobile-participation"><div><small>${t('方案付款 · Gas 另计','Draft payment · gas separate')}</small><b id="detail-mobile-cost">—</b></div><button class="button primary" data-action="participate" aria-label="${t('底部生成 Agent 参与方案','Prepare Agent brief from bottom bar')}">${t('交给 Agent','For my Agent')} ↗</button></div>`:''}`;
}

function field(k,{hint='',suffix='',textarea=false,select=false}={}){
 const labels=formLabels(),error=state.errors[k],id=`field-${k}`,optional=['website','x','telegram','cover'].includes(k),description=`aria-describedby="hint-${k} error-${k}"`,invalid=error?'aria-invalid="true"':'';
 let input;
 if(select)input=`<select id="${id}" data-field="${k}" ${invalid} ${description}>${['tools','creative','community'].map(v=>`<option value="${v}" ${state.form[k]===v?'selected':''}>${category(v)}</option>`).join('')}</select>`;
 else if(textarea)input=`<textarea id="${id}" data-field="${k}" maxlength="2000" ${invalid} ${description}>${escape(state.form[k])}</textarea>`;
 else input=`<div class="input-suffix"><input id="${id}" data-field="${k}" value="${escape(state.form[k])}" ${['shares','allocation','limit','maxTx','liquidity','days'].includes(k)?'inputmode="numeric"':k==='price'?'inputmode="decimal"':''} type="${['website','x','telegram'].includes(k)?'url':'text'}" ${invalid} ${description} ${k==='name'?'maxlength="32"':k==='symbol'?'maxlength="10"':k==='tagline'?'maxlength="100"':''}>${suffix?`<span>${suffix}</span>`:''}</div>`;
 return `<div class="field ${textarea||['tagline','website'].includes(k)?'wide':''}"><label for="${id}">${labels[k]}${!optional?'<small>*</small>':''}</label>${input}<p class="hint" id="hint-${k}">${hint}</p><p class="error" id="error-${k}">${error?messages()[error]:''}</p></div>`;
}

function coverImage(value,alt,extra=''){return `<div class="draft-cover-image ${extra}">${value&&validCover(value)?`<img class="project-cover-image" src="${escape(value)}" alt="${escape(alt)}" referrerpolicy="no-referrer">`:`<span class="cover-placeholder" aria-hidden="true">＋</span>`}<span class="cover-image-error" hidden>${t('封面无法显示，请重新选择图片','Cover unavailable. Choose another image.')}</span></div>`;}
function coverEditor(){const f=state.form;return `<section class="cover-editor" aria-label="${t('项目封面设置','Project cover settings')}">${coverImage(f.cover,t('项目封面预览','Project cover preview'))}<div><h3>${t('项目封面（选填）','Project cover (optional)')}</h3><p>${t('这张图片会用于项目卡片和详情展示。选择你自己的图片，先看看效果。','This image appears on the project card and detail page. Choose your own image to preview it.')}</p><button class="button small" type="button" data-action="choose-cover">${t('选择封面图片','Choose cover image')} ↥</button><input id="cover-file" type="file" accept="image/jpeg,image/png,image/webp" hidden>${f.cover?`<button class="text-button" data-action="remove-cover">${t('移除封面','Remove cover')}</button>`:''}<p class="mini-note">${t('JPG / PNG / WebP · 最大 2 MB。图片只存本地，不上传。','JPG / PNG / WebP · Up to 2 MB. Stored locally, never uploaded.')}</p><p class="error" id="cover-status" role="status">${state.errors.cover?messages().cover:''}</p></div></section>`;}
function draftCardPreview(){const f=state.form;return `<section class="draft-card-preview" aria-label="${t('项目展示实时预览','Live project card preview')}"><div class="preview-card-title"><span>${t('项目展示预览','LIVE CARD PREVIEW')}</span><span>${t('本地草稿','LOCAL DRAFT')}</span></div>${coverImage(f.cover,t('草稿项目封面','Draft project cover'))}<div class="preview-card-copy"><h3 id="card-preview-name">${escape(f.name)||t('你的项目名称','Your project name')}</h3><small>${escape(f.symbol?'$'+f.symbol:'$TOKEN')} · AGENT-ONLY</small><p>${escape(f.tagline)||t('你填写的一句话介绍会显示在这里。','Your one-line introduction appears here.')}</p><div class="kv"><b>${escape(f.price)||'—'} BNB / ${t('份','share')}</b><span>${t('尚未发布','NOT PUBLISHED')}</span></div></div></section>`;}

function summary(){return draftCardPreview()+(state.step===1?`<details class="preview-budget"><summary>${t('查看发行参数预览','Preview issuance numbers')}</summary>${financialSummary()}</details>`:financialSummary());}
function financialSummary(){const f=state.form;let m;try{m=economics(f);}catch{}return `<div class="summary-card"><div class="eyebrow" style="margin-bottom:12px">YOUR LAUNCH / PREVIEW</div><h3>${escape(f.name)||t('你的下一个开始','Your next beginning')}</h3><div class="muted">${escape(f.symbol?`$${f.symbol}`:t('固定价格发行模板','Fixed-price launch template'))}</div><div class="summary-total"><span class="muted" style="font-size:10px">${t('示例募集目标','Illustrative raise target')}</span><strong>${m?u(m.raisedWei):'—'} <small style="font:12px var(--sans)">BNB</small></strong></div><div class="kv"><span>${t('参与分配','Participant allocation')}</span><b>${m?u(m.soldWei):'—'}</b></div><div class="kv"><span>${t('流动性代币','Liquidity tokens')}</span><b>${m?u(m.poolTokensWei):'—'}</b></div><div class="kv"><span>${t('总供应量','Total token supply')}</span><b>${m?u(m.totalSupplyWei):'—'}</b></div><div class="divider"></div><div class="kv"><span>${t('入池资金','Liquidity funds')}</span><b>${m?u(m.liquidityWei):'—'} BNB</b></div><div class="kv"><span>${t('项目方资金','Project funds')}</span><b>${m?u(m.projectWei):'—'} BNB</b></div><div class="kv"><span>${t('平台费','Platform fee')}</span><b>${t('未设置','Not configured')}</b></div><div class="summary-extra"><div class="divider"></div><p class="mini-note">${t('这些数值只属于你正在编辑的新项目方案，不是 ECHO 现有代币或 Mint 的参数。','These values belong only to this new project draft, not to the existing ECHO token or Mint.')}</p></div></div>`;}
function stepBody(){
 const f=state.form,record=drafts.find(d=>d.id===state.id),ready=canShowcase(record);
 if(state.step===1)return `<div class="builder-intro"><div><h2>${t('先把项目介绍清楚。','Start with a clear project.')}</h2><p>${t('封面和简介用于项目卡片，项目说明用于详情页。','The cover and introduction appear on the card; the description explains the project in detail.')}</p></div><button class="text-button" data-action="agent-create">${t('让 Agent 帮我填写','Prepare with my Agent')} ↗</button></div><button class="text-button example-loader" data-action="fill-example">${t('载入完整示例','Load a complete example')} ↗</button>${coverEditor()}<div class="fields">${field('name',{hint:t('2–32 字，使用容易辨认的项目名称。','2–32 characters; use a recognizable name.')})}${field('symbol',{hint:t('2–10 位大写字母或数字，首位为字母。','2–10 uppercase letters/digits, starting with a letter.')})}${field('tagline',{hint:t('6–100 字，说明项目提供什么。','6–100 characters describing what the project offers.')})}${field('description',{textarea:true,hint:t('20–2,000 字，说明产品、参与者和计划交付的内容。','20–2,000 characters covering the product, participants and planned deliverables.')})}</div><details class="optional-fields" ${state.errors.x||state.errors.telegram||state.errors.website?'open':''}><summary>${t('分类与链接（选填展示信息）','Category and links (optional presentation details)')}</summary><div class="fields">${field('category',{select:true,hint:t('只用于项目筛选，不影响价格、额度、资格或资金规则。','For directory filtering only. Does not change price, caps, eligibility or funding.')})}${field('website',{hint:t('可选 HTTPS 官网；外部网站尚未核验。','Optional HTTPS website; external sites are unverified.')})}${field('x',{hint:t('可选：https://x.com/你的账号','Optional: https://x.com/your-account')})}${field('telegram',{hint:t('可选：https://t.me/你的社群','Optional: https://t.me/your-community')})}</div></details>`;
 if(state.step===2)return `<div class="builder-intro"><div><h2>${t('一套清楚的发行规则。','One clear set of launch terms.')}</h2><p>${t('下面是新项目的可编辑方案值，不是 ECHO 现有 Mint 参数。','Editable proposed values for a new project, separate from the existing ECHO Mint.')}</p></div></div><div class="template-locks"><span>BNB Chain / 56</span><span>Agent-only</span><span>${t('固定价格','Fixed price')}</span><span>${t('满额开盘','Full-raise opening')}</span></div><div class="fields">${field('shares',{hint:t('所有参与者合计可购买的总份数。','Total shares available to all participants.')})}${field('allocation',{hint:t('每份对应的代币数量。','Tokens allocated per share.')})}${field('price',{suffix:'BNB',hint:t('最多 18 位小数；网络 Gas 另计。','Up to 18 decimal places; network gas is separate.')})}${field('days',{suffix:t('天','days'),hint:t('正式发行开始后的募集期，1–30 天。','1–30 days after the official launch start.')})}${field('limit',{hint:t('每个官方 .ai 身份的累计份额上限。','Lifetime share cap for each official .ai identity.')})}${field('maxTx',{hint:t('不得超过身份累计上限；1–100 份。','1–100 shares, not exceeding the identity cap.')})}</div><div class="allocation-setting"><h3>${t('满额后，募集资金如何分配？','How would the raised funds be allocated?')}</h3>${field('liquidity',{suffix:'%',hint:t('50–100% 用于建池；其余在满额时分配给项目方。','50–100% for liquidity; the remainder goes to the project after a full raise.')})}</div><div class="warning">${t('未满额到期：拟允许参与者主动退回 Mint 本金，Gas 不退。资金托管、退款及 LP 销毁仍需未来合约实现。','Unfilled after expiry: proposed participant-initiated refunds of Mint payments, excluding gas. Escrow, refunds and LP burn still require future contract implementation.')}</div>`;
 if(state.step===3){const m=economics(f);return `<h2>${t('确认完整方案，再交给 Agent。','Review the complete draft before handoff.')}</h2><p>${t('核对项目资料、价格、额度和资金用途。所有参数仍是待正式确认的方案。','Check the identity, price, caps and allocation. These remain proposed terms awaiting formal confirmation.')}</p><div class="review-group review-project"><div><h3>${escape(f.name)}</h3><span>$${escape(f.symbol)} · ${category(f.category)}</span><p>${escape(f.tagline)}</p></div><button class="text-button" data-step="1">${t('修改资料','Edit identity')} ↗</button></div><div class="review-numbers"><div><span>${t('每份价格','Price per share')}</span><b>${escape(f.price)} BNB</b></div><div><span>${t('每份代币','Tokens per share')}</span><b>${n(f.allocation)} ${escape(f.symbol)}</b></div><div><span>${t('募集目标','Raise target')}</span><b>${u(m.raisedWei)} BNB</b></div><div><span>${t('总供应量','Total token supply')}</span><b>${u(m.totalSupplyWei)}</b></div></div><div class="review-group"><div class="inline-heading"><h3>${t('完整发行约定','Complete launch terms')}</h3><button class="text-button" data-step="2">${t('修改规则','Edit rules')} ↗</button></div>${rules(f)}</div><div class="review-readiness"><p>✓ ${t('项目必填信息完整','Required project information complete')}</p><p>✓ ${t('份额、额度与资金分配通过校验','Shares, caps and allocations validated')}</p><p>↳ ${t('合约未部署，链上状态与 Gas 未核验','Contracts not deployed; chain state and gas unverified')}</p></div><label class="check-row"><input type="checkbox" id="confirm-preview" ${state.confirmed?'checked':''}><span>${t('我已核对这份方案，理解本次仅生成本地草稿与展示，不发行代币、不收款、不授权钱包。','I reviewed this draft and understand it creates local records and previews only, with no token issuance, payments or wallet authorization.')}</span></label><div class="error" id="confirm-error" role="status"></div>`;}
 return `<div class="success-icon" aria-hidden="true">✓</div><h2>${ready?t('方案已审阅，接下来怎么做？','Reviewed. What would you like to do next?'):t('方案已保存，请重新完成审阅。','Draft saved. Complete the review again.')}</h2><p>${t('可以在本地展示、预览详情，或把完整 JSON 与指令交给自己的 Agent。','Showcase it locally, preview the details, or hand the complete JSON and brief to your Agent.')}</p><div class="local-publish-panel"><div><span class="eyebrow">LOCAL SHOWCASE</span><h3>${record?.listed?t('你的项目已加入本地展示','Your project is in the local showcase'):t('先看看它出现在列表里的样子。','See how it looks in the project market.')}</h3><p>${t('仅当前浏览器可见，不是公开上架或链上发行。','Visible in this browser only. This is not a public listing or on-chain launch.')}</p></div><button class="button primary full" data-action="${!ready?'review-again':record?.listed?'go-local':'showcase'}">${!ready?t('重新审阅并确认','Review and confirm'):record?.listed?t('查看本地项目列表','View my local showcase'):t('加入本地展示','Add to local showcase')} ↗</button></div><div class="handoff-actions"><button class="button primary" data-action="copy-create">${t('复制给我的 Agent','Copy for my Agent')} ↗</button><button class="button" data-action="export-draft">${t('下载完整 JSON','Download full JSON')} ↓</button><button class="button" data-action="preview-draft">${t('预览项目详情','Preview project details')} ↗</button><a class="button" href="#/drafts">${t('管理我的项目','Manage my projects')}</a></div><details class="agent-output"><summary>${t('展开完整 Agent 审阅指令','Expand the complete Agent review brief')}</summary><textarea class="code-box" id="launch-brief" readonly aria-label="${t('发行方案 Agent 指令','Launch draft Agent brief')}">${escape(agentBrief(f,state.lang,'create',1,new URL('./',location.href).href,state.id))}</textarea></details><details class="live-requirements"><summary>${t('未来进入正式发行，还需要什么？','What is needed for a future live launch?')}</summary><ul><li>${t('用户正式确认经济规则、收费与资金安排。','User confirmation of economics, fees and fund handling.')}</li><li>${t('实现、检查并部署发行合约，提供官方配置。','Implement, review and deploy issuance contracts with official configuration.')}</li><li>${t('核验身份、最新链上状态、费用与用户授权。','Verify identity, current chain state, exact costs and user consent.')}</li></ul></details>`;
}

function builder(){
 const names=[t('项目资料','Project'),t('发行规则','Rules'),t('审阅确认','Review'),t('保存与交接','Handoff')];
 return `<main id="main" class="wrap section builder-page"><div class="section-heading"><div><div class="eyebrow">LAUNCH STUDIO / FIXED-PRICE 01</div><h1>${t('把想法，变成一份完整方案。','Build a complete launch brief.')}</h1><p>${t('填写 → 审阅 → 本地展示 → Agent 交接。','Configure → review → local showcase → Agent handoff.')}</p></div><div class="page-actions"><button class="text-button" data-action="agent-create">${t('Agent 帮我创建','Prepare with Agent')} ↗</button><button class="text-button" data-action="import">${t('导入 JSON','Import JSON')} ↥</button></div></div><div class="steps" aria-label="${t('发行步骤','Launch steps')}">${names.map((name,i)=>`<button class="step ${state.step===i+1?'current':i+1<state.step?'done':''}" data-step="${i+1}" ${i+1>state.step?'disabled':''} ${state.step===i+1?'aria-current="step"':''}><span>${i+1<state.step?'✓':'0'+(i+1)}</span>${name}</button>`).join('')}</div><div class="builder-grid"><section class="builder-main"><div class="builder-panel">${stepBody()}</div><div class="builder-actions"><button class="button" data-action="${state.step===1?'to-market':'previous'}">← ${state.step===1?t('返回市场','Back to market'):t('上一步','Previous')}</button>${state.step<4?`<button class="button primary" data-action="next">${state.step===3?t('确认并保存方案','Confirm and save draft'):t('保存并继续','Save and continue')} ↗</button>`:`<button class="text-button" data-step="2">${t('返回修改规则','Edit launch rules')} ↗</button>`}</div><p id="save-state" class="save-state" role="status">${storageError?t('最新变更尚未保存，请导出 JSON。','Latest changes are not saved. Export JSON.'):t('草稿只保存在当前浏览器。可用 JSON 移动到其他设备。','Drafts stay in this browser. Use JSON to move between devices.')}</p></section><aside class="builder-aside" id="builder-summary">${summary()}</aside></div></main>`;
}

function draftsPage(){
 const selected=drafts.filter(d=>state.draftFilter==='all'||(state.draftFilter==='shown'?d.listed&&canShowcase(d):!d.listed||!canShowcase(d)));
 return `<main id="main" class="wrap section workspace-page"><div class="section-heading"><div><div class="eyebrow">YOUR PROJECT WORKSPACE</div><h1>${t('从草稿，走到下一步。','Keep your next launch moving.')}</h1><p>${t('继续编辑、导出给 Agent，或管理你在本地展示的项目。','Continue editing, export for your Agent or manage local showcases.')}</p></div><div class="page-actions"><button class="button small" data-action="import">${t('导入 JSON','Import JSON')} ↥</button><button class="button primary small" data-action="new">${t('新建项目','New project')} ↗</button></div></div><div class="workspace-tabs">${[['all',t('全部项目','All projects')],['drafts',t('草稿','Drafts')],['shown',t('本地展示','Local showcases')]].map(([key,label])=>`<button class="chip" data-draft-filter="${key}" aria-pressed="${state.draftFilter===key}">${label}</button>`).join('')}<span>${selected.length} ${t('个项目','PROJECTS')}</span></div>${selected.length?`<div class="draft-grid">${selected.map(d=>{const complete=!Object.keys(validateForm(d.form)).length,reviewed=canShowcase(d),shown=d.listed&&reviewed;return `<article class="draft-card"><div class="card-top"><span class="eyebrow">FIXED-PRICE / 01</span><span class="badge draft">${shown?t('本地展示','Local showcase'):reviewed?t('已审阅','Reviewed'):complete?t('待审阅','Needs review'):t('填写中','In progress')}</span></div><h3>${escape(d.form.name)||t('未命名项目','Untitled project')}</h3><p>${escape(d.form.tagline)||t('添加名称与介绍，准备你的第一份发行方案。','Add a name and introduction to prepare a launch brief.')}</p><div class="draft-meta">${escape(d.form.symbol?'$'+d.form.symbol+' · ':'')}${t('尚未发行','Not issued')} · ${Number.isNaN(Date.parse(d.updatedAt))?'—':new Date(d.updatedAt).toLocaleDateString(state.lang==='zh'?'zh-CN':'en-US')}</div><div class="draft-actions"><button class="button primary small" data-edit="${escape(d.id)}">${t('继续编辑','Continue editing')} ↗</button>${complete?`<a class="button small" href="#/project/${escape(d.id)}">${t('详情预览','View details')}</a><button class="text-button" data-export="${escape(d.id)}">JSON ↓</button>`:''}<button class="text-button" data-duplicate="${escape(d.id)}">${t('复制方案','Duplicate')}</button>${shown?`<button class="text-button" data-unlist="${escape(d.id)}">${t('移出展示','Remove showcase')}</button>`:''}<button class="text-button draft-delete" data-delete="${escape(d.id)}">${t('删除','Delete')}</button></div></article>`;}).join('')}</div>`:`<div class="empty"><h2>${t('这里还没有项目。','No projects here yet.')}</h2><p>${t('创建一份方案，或导入 Agent 准备的 JSON。','Create a draft or import JSON prepared by your Agent.')}</p><button class="button primary" data-action="new">${t('创建发行方案','Create a launch')} ↗</button></div>`}<div class="workspace-note"><p>${t('本地展示只用于体验，不会公开上架。修改已展示方案后，需要重新审阅再展示。','Local showcases are for this preview only, never public listings. Review and showcase again after editing.')}</p><p>${t('清除浏览器数据可能删除项目，请及时下载 JSON 备份。','Clearing browser data may remove projects. Download JSON to keep a backup.')}</p></div></main>`;
}

function agentPage(){
 return `<main id="main" class="wrap section agent-page"><div class="agent-intro"><div><div class="eyebrow">BUILT FOR AGENTS. REVIEWED BY YOU.</div><h1>${t('让 Agent，<br>直接读懂你的方案。','Clear inputs.<br>Clear handoffs.')}</h1><p>${t('表单、结构化 JSON 和审阅指令使用同一套参数。可以自己填，也可以让 Agent 准备后再导入。','The form, structured JSON and review brief use the same parameters. Fill it yourself or import a draft prepared by your Agent.')}</p><div class="hero-buttons"><button class="button primary" data-action="agent-create">${t('复制 Agent 创建指令','Copy Agent drafting prompt')} ↗</button><button class="button" data-action="import">${t('导入 Agent 方案','Import Agent draft')} ↥</button></div></div><div class="agent-flag">schema: <strong>${SCHEMA}</strong><br>chainId: <strong>56</strong><br>executionReady: <strong>false</strong><br>contracts.launch: <strong>null</strong><br>mode: <strong>local draft review</strong></div></div><div class="agent-steps"><article><span>01</span><h3>${t('告诉 Agent 你的项目','Describe your project')}</h3><p>${t('提供名称、简介和计划参数。未确定的经济规则由你确认。','Provide the name, introduction and intended parameters. Confirm any undecided economics yourself.')}</p></article><article><span>02</span><h3>${t('导入并校验 JSON','Import and validate JSON')}</h3><p>${t('Agent 按公开格式输出方案。导入后检查字段与金额，不直接执行。','Your Agent returns the public format. Import it to validate fields and costs without executing it.')}</p></article><article><span>03</span><h3>${t('审阅，再保留一份','Review and keep a copy')}</h3><p>${t('核对完整规则，保存 JSON，或加入本地展示体验详情。','Review all terms, keep the JSON or add a local showcase to explore the detail page.')}</p></article></div><div class="guide-grid"><section class="panel"><h2>${t('机器可读资料','Machine-readable references')}</h2><p class="body-copy">${t('这些是当前预览的公开格式。你的本地草稿通过导出文件交接，不会变成公网接口。','These describe the preview format. Local drafts are exchanged as files, not public endpoints.')}</p><div class="agent-files"><a href="./agent-guide.md" target="_blank" rel="noopener"><b>agent-guide.md</b><span>${t('规则与停止条件','Rules and stop conditions')} ↗</span></a><a href="./schema.json" target="_blank" rel="noopener"><b>schema.json</b><span>${t('字段与 JSON 格式','Fields and JSON format')} ↗</span></a><a href="./examples.json" target="_blank" rel="noopener"><b>examples.json</b><span>${t('三份可导入示例','Three importable examples')} ↗</span></a><a href="./llms.txt" target="_blank" rel="noopener"><b>llms.txt</b><span>${t('Agent 资料索引','Agent reference index')} ↗</span></a></div></section><section class="panel"><h2>${t('参与者也能直接交接','Participants can hand off directly')}</h2><p class="body-copy">${t('在项目详情里选择份数，再复制完整参与方案。指令会保留项目规则、整数 wei 金额和执行停止条件。','Choose shares on a project detail page and copy the complete participation brief. It retains the terms, exact integer-wei cost and execution stop conditions.')}</p><a class="button" href="#/project/aurum-studio">${t('体验参与流程','Try the participation flow')} ↗</a><div class="warning" style="margin-top:22px">${t('当前没有真实发行合约，不连接钱包、不请求签名。Agent 只审阅；未来执行需要独立配置与用户授权。','No live issuance contracts are connected. There is no wallet connection or signing. Agents review only; future execution needs verified configuration and separate consent.')}</div></section></div></main>`;
}

function route(){const parts=location.hash.replace(/^#\/?/,'').split('/');if(!parts[0]||parts[0]==='projects')return['projects',['published','local','examples'].includes(parts[1])?parts[1]:'published'];if(['create','drafts','agent'].includes(parts[0]))return[parts[0]];if(parts[0]==='project'){try{return['project',decodeURIComponent(parts[1]||'')];}catch{return['project',''];}}return['projects','published'];}

function render(){
 const[r,id]=route();if(r==='projects')state.catalog=id;
 document.documentElement.lang=state.lang==='zh'?'zh-CN':'en';
 document.title=`ECHO Launch — ${r==='project'?(projectFor(id)?.f.name||t('项目详情','Project details')):r==='create'?t('发起项目','Create a project'):r==='drafts'?t('我的项目','My projects'):r==='agent'?t('Agent 文档','For agents'):t('项目市场','Project market')}`;
 const body= r==='projects'?market():r==='create'?builder():r==='drafts'?draftsPage():r==='agent'?agentPage():projectPage(id);
 app.innerHTML=header(r)+body+footer();
 document.body.classList.toggle('has-mobile-action',r==='project'&&!!projectFor(id)&&projectFor(id).p.phase!=='opened');
 if(r==='project')updateQuote();
}

function updateResults(){if(!$('project-results'))return;$('project-results').innerHTML=projectResults();$('result-count').textContent=`${matching().length} ${t('个项目','PROJECTS')}`;}

function updateQuote(){
 const p=projectFor(route()[1]);if(!p||!$('quote-payment'))return;
 const cap=Math.min(Number(p.f.maxTx),Number(p.f.limit));let valid=false;
 try{const q=previewQuote(p.f,state.quantity);$('quote-payment').textContent=`${u(q.paymentWei)} BNB`;$('quote-tokens').textContent=`${u(q.tokensWei)} ${p.f.symbol}`;$('quote-error').textContent='';if($('detail-mobile-cost'))$('detail-mobile-cost').textContent=`${u(q.paymentWei)} BNB`;valid=true;}catch{$('quote-payment').textContent='—';$('quote-tokens').textContent='—';$('quote-error').textContent=t(`请输入 1–${cap} 的整数份数。`,`Enter a whole number from 1 to ${cap}.`);if($('detail-mobile-cost'))$('detail-mobile-cost').textContent='—';}
 app.querySelectorAll('[data-action="participate"]').forEach(el=>el.disabled=!valid);
 const minus=app.querySelector('[data-action="minus"]'),plus=app.querySelector('[data-action="plus"]');if(minus)minus.disabled=Number(state.quantity)<=1;if(plus)plus.disabled=Number(state.quantity)>=cap;
}

function openModal(title,body){dialog.innerHTML=`<div class="modal-head"><h2 id="dialog-title">${title}</h2><button class="close" data-action="close-modal" aria-label="${t('关闭弹窗','Close dialog')}">×</button></div><div class="modal-body">${body}</div>`;dialog.showModal();}
async function copy(value){try{await navigator.clipboard.writeText(value);toast(t('完整指令已复制，可发送给自己的 Agent。','Complete brief copied. Send it to your own Agent.'));}catch{openModal(t('手动复制指令','Copy the brief manually'),`<p>${t('浏览器未允许自动复制。请选择下方完整文本后复制。','Automatic clipboard access was unavailable. Select and copy the complete text below.')}</p><textarea class="code-box" id="manual-copy" readonly aria-label="${t('手动复制文本','Text to copy manually')}">${escape(value)}</textarea>`);$('manual-copy').select();}}
function download(f,id){const m=manifestFor(f,id),blob=new Blob([JSON.stringify(m,null,2)+'\n'],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`echo-launch-${f.symbol.toLowerCase()}-draft.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('JSON 已导出；请检查浏览器下载。','JSON exported. Check your browser downloads.'));}
function participation(){
 const result=projectFor(route()[1]);if(!result)return;
 const{f,p}=result,done=p.phase==='opened';let q=null;
 if(!done){try{q=previewQuote(f,state.quantity);}catch{updateQuote();$('quote-quantity')?.focus();return;}}
 const brief=agentBrief(f,state.lang,done?'project-review':'participation-review',done?0:Number(state.quantity),new URL('./',location.href).href,p.id);
 openModal(t('把完整方案交给你的 Agent','Hand the complete brief to your Agent'),`<div class="brief-project"><b>${escape(f.name)}</b><span>$${escape(f.symbol)} · BNB Chain / 56</span></div>${q?`<dl class="brief-summary"><div><dt>${t('选择份数','Shares')}</dt><dd>${q.quantity}</dd></div><div><dt>${t('代币分配','Token allocation')}</dt><dd>${u(q.tokensWei)} ${escape(f.symbol)}</dd></div><div><dt>${t('方案付款','Draft payment')}</dt><dd>${u(q.paymentWei)} BNB</dd></div><div><dt>${t('Gas','Network gas')}</dt><dd>${t('另计，尚未估算','Separate, not estimated')}</dd></div></dl>`:''}<div class="warning">${t('只审阅方案。合约、身份与实时费用尚未核验，Agent 应停止交易执行。','Review only. Contracts, identity and live costs are unverified. The Agent must stop before executing transactions.')}</div><details class="brief-details"><summary>${t('查看完整 Agent 指令','View the complete Agent brief')}</summary><textarea class="code-box" id="participation-brief" readonly aria-label="${t('Agent 参与方案指令','Agent participation brief')}">${escape(brief)}</textarea></details><button class="button primary full" data-action="copy-participation">${t('复制给我的 Agent','Copy for my Agent')} ↗</button><button class="button full" data-action="export-project">${t('下载完整项目 JSON','Download full project JSON')} ↓</button>`);
}

function openImport(){openModal(t('导入发行方案','Import a launch draft'),`<p>${t('选择或粘贴 ECHO Launch JSON。导入后保存在当前浏览器，需重新审阅。最大 512 KB。','Choose or paste ECHO Launch JSON. It stays in this browser and needs a new review. Maximum 512 KB.')}</p><button class="button small" data-action="choose-import">${t('选择 JSON 文件','Choose JSON file')} ↥</button><input type="file" id="import-file" accept=".json,application/json" hidden><textarea class="import-text" id="import-json" placeholder="${SCHEMA}" aria-label="${t('发行方案 JSON','Launch draft JSON')}"></textarea><p class="error" id="import-error" role="status"></p><button class="button primary full" data-action="confirm-import">${t('验证并导入','Validate and import')} ↗</button>`);}


function finishNavigation(){if(pendingScroll)document.getElementById(pendingScroll)?.scrollIntoView({block:'start'});else window.scrollTo({top:0,behavior:'instant'});pendingScroll='';}
function resetFilters(){state.search='';state.category='all';state.phase='all';state.sort='featured';}
function openAgentCreate(){const prompt=agentDraftPrompt(state.lang,new URL('./',location.href).href);openModal(t('让 Agent 帮你准备方案','Prepare a draft with your Agent'),`<p>${t('复制下面的指令，让 Agent 先读取规则，再收集你的项目信息和参数。生成 JSON 后回到这里导入、审阅。','Copy this prompt so your Agent reads the rules and collects your project information and parameters. Return here to import and review the generated JSON.')}</p><textarea class="code-box" id="agent-create-prompt" readonly aria-label="${t('Agent 创建方案指令','Agent drafting prompt')}">${escape(prompt)}</textarea><button class="button primary full" data-action="copy-agent-create">${t('复制 Agent 创建指令','Copy Agent drafting prompt')} ↗</button><button class="button full" data-action="switch-to-import">${t('我已有 JSON，导入方案','I have JSON · import draft')} ↥</button>`);}

function draftStep(draft){if(Object.keys(validateForm(draft.form,1)).length)return 1;if(Object.keys(validateForm(draft.form,2)).length)return 2;return Math.max(1,Math.min(4,Number(draft.step)||1));}

app.addEventListener('input',event=>{
 const el=event.target;
 if(el.matches('[data-field]')){
  const key=el.dataset.field;state.form[key]=key==='symbol'?el.value.toUpperCase():el.value;if(key==='symbol')el.value=state.form[key];state.confirmed=false;delete state.errors[key];el.removeAttribute('aria-invalid');if($(`error-${key}`))$(`error-${key}`).textContent='';
  const previouslyListed=drafts.find(d=>d.id===state.id)?.listed;
  persist();saveState();if($('builder-summary'))$('builder-summary').innerHTML=summary();
  if(previouslyListed&&!drafts.find(d=>d.id===state.id)?.listed)toast(t('修改已保存。重新审阅后可加入本地展示。','Changes saved. Review again before showcasing locally.'));
 }
 if(el.id==='project-search'){state.search=el.value;updateResults();}
 if(el.id==='quote-quantity'){state.quantity=el.value;updateQuote();}
});

app.addEventListener('change',event=>{
 const el=event.target;
 if(el.id==='category-filter'){state.category=el.value;updateResults();}
 if(el.id==='sort-projects'){state.sort=el.value;updateResults();}
 if(el.id==='confirm-preview')state.confirmed=el.checked;
});

document.addEventListener('click',async event=>{
 const skip=event.target.closest('a[href="#main"]');
 if(skip){event.preventDefault();const main=$('main');if(main){main.tabIndex=-1;main.focus();main.scrollIntoView({block:'start'});}return;}
 const el=event.target.closest('button,[data-action]');if(!el||el.disabled)return;
 const action=el.dataset.action;
 if(el.dataset.catalog){resetFilters();setHash(`#/projects/${el.dataset.catalog}`,'projects');return;}
 if(el.dataset.view){state.view=el.dataset.view;try{localStorage.setItem(VIEW,JSON.stringify(state.view));}catch{}render();return;}
 if(el.dataset.phase){state.phase=el.dataset.phase;render();return;}
 if(el.dataset.draftFilter){state.draftFilter=el.dataset.draftFilter;render();return;}
 if(el.dataset.tab){state.tab=el.dataset.tab;render();$(`detail-tab-${state.tab}`)?.focus({preventScroll:true});return;}
 if(el.dataset.step){state.step=Number(el.dataset.step);state.confirmed=false;state.errors={};render();document.querySelector('.steps')?.scrollIntoView({block:'start'});return;}
 if(el.dataset.edit){const draft=drafts.find(d=>d.id===el.dataset.edit);if(draft){state.form={...draft.form};state.id=draft.id;state.step=draftStep(draft);state.confirmed=false;state.errors={};setHash('#/create');}return;}
 if(el.dataset.export){const draft=drafts.find(d=>d.id===el.dataset.export);if(draft)download(draft.form,draft.id);return;}
 if(el.dataset.duplicate){const draft=drafts.find(d=>d.id===el.dataset.duplicate);if(draft){state.form={...draft.form,name:(draft.form.name||t('新项目','New project')).slice(0,25)+t(' 副本',' copy')};state.id=null;state.step=1;state.confirmed=false;state.errors={};persist();setHash('#/create');toast(t('已复制为新的本地草稿。','Duplicated as a new local draft.'));}return;}
 if(el.dataset.unlist){const index=drafts.findIndex(d=>d.id===el.dataset.unlist);if(index>=0){const next=[...drafts];next[index]=updateDraft(next[index],next[index].form,{step:next[index].step,listed:false});try{localStorage.setItem(KEY,JSON.stringify(next));drafts=next;render();toast(t('已移出本地展示，草稿仍保留。','Removed from local showcase. The draft is retained.'));}catch{toast(t('未能保存变更，请先导出 JSON。','Could not save changes. Export JSON first.'),true);}}return;}
 if(el.dataset.delete){openModal(t('删除这份本地草稿？','Delete this local draft?'),`<p>${t('只删除当前浏览器中的这份方案。建议先下载 JSON，删除后不能从页面恢复。','Removes this draft from this browser only. Download JSON first; this action cannot be undone from the page.')}</p><button class="button" data-action="close-modal">${t('保留草稿','Keep draft')}</button> <button class="button primary" data-action="delete-confirm" data-id="${escape(el.dataset.delete)}">${t('确认删除','Delete draft')}</button>`);return;}
 if(action==='language'){state.lang=state.lang==='zh'?'en':'zh';try{localStorage.setItem(LANG,JSON.stringify(state.lang));}catch{}render();return;}
 if(action==='new'){newDraft();return;}
 if(action==='close-modal'){dialog.close();return;}
 if(action==='choose-cover'){$('cover-file')?.click();return;}
 if(action==='choose-import'){$('import-file')?.click();return;}
 if(action==='remove-cover'){state.form.cover='';state.confirmed=false;delete state.errors.cover;persist();render();return;}
 if(action==='scroll-projects'){$('projects')?.scrollIntoView({block:'start',behavior:'smooth'});return;}
 if(action==='clear-filters'){resetFilters();render();return;}
 if(action==='agent-create'){openAgentCreate();return;}
 if(action==='copy-agent-create'){await copy($('agent-create-prompt').value);return;}
 if(action==='switch-to-import'){dialog.close();openImport();return;}
 if(action==='help'){openModal(t('从发现项目，到完整发行方案。','From project discovery to a complete brief.'),`<ol class="journey-list"><li><span>01</span><div><h3>${t('浏览演示项目','Explore examples')}</h3><p>${t('切换图片网格或紧凑列表，打开项目查看规则。','Switch between cover grid and compact list, then open a project for its terms.')}</p></div></li><li><span>02</span><div><h3>${t('创建并审阅自己的方案','Create and review your own draft')}</h3><p>${t('自己填写或让 Agent 准备 JSON，完成四步向导。','Fill the form or import Agent-prepared JSON, then complete the four-step guide.')}</p></div></li><li><span>03</span><div><h3>${t('加入本地展示','Add a local showcase')}</h3><p>${t('在本地列表查看你的项目。只有当前浏览器可见，不会发币或收款。','See your project in the local list. It stays in this browser, with no issuance or payments.')}</p></div></li></ol><button class="button primary full" data-action="close-modal">${t('开始体验','Start exploring')} ↗</button>`);return;}
 if(action==='fill-example'){state.form=sampleForm(SAMPLES[0],state.lang);state.errors={};state.confirmed=false;persist();render();toast(t('已载入示例。请替换为自己的信息并确认参数。','Example loaded. Replace its details and confirm your own parameters.'));return;}
 if(action==='next'){
  state.errors=validateForm(state.form,state.step<=2?state.step:0);
  if(Object.keys(state.errors).length){render();const key=Object.keys(state.errors)[0],field=$(`field-${key}`);if(field){const details=field.closest('details');if(details)details.open=true;field.focus();}else $('cover-file')?.focus();toast(t('请检查标出的字段。','Check the highlighted fields.'),true);return;}
  if(state.step===3&&!state.confirmed){$('confirm-error').textContent=t('请先核对并确认这是一份本地方案。','Review and acknowledge that this is a local draft first.');$('confirm-preview').focus();return;}
  const reviewing=state.step===3;state.step=Math.min(4,state.step+1);const saved=persist({review:reviewing});render();document.querySelector('.steps')?.scrollIntoView({block:'start'});if(!saved)toast(t('浏览器未能保存方案。请先下载 JSON。','The browser could not save the draft. Download JSON to keep it.'),true);return;
 }
 if(action==='previous'){state.step=Math.max(1,state.step-1);state.errors={};render();document.querySelector('.steps')?.scrollIntoView({block:'start'});return;}
 if(action==='review-again'){state.step=3;state.confirmed=false;render();return;}
 if(action==='to-market'){setHash('#/projects');return;}
 if(action==='go-local'){setHash('#/projects/local','projects');return;}
 if(action==='showcase'){if(!canShowcase(drafts.find(d=>d.id===state.id))){state.step=3;state.confirmed=false;render();toast(t('请先完成方案审阅。','Complete the draft review first.'),true);return;}if(persist({listed:true})){resetFilters();setHash('#/projects/local','projects');toast(t('已加入本地展示，仅当前浏览器可见。','Added to the local showcase, visible only in this browser.'));}else toast(t('未能保存展示。请先下载 JSON。','Could not save the showcase. Download JSON first.'),true);return;}
 if(action==='copy-create'){await copy(agentBrief(state.form,state.lang,'create',1,new URL('./',location.href).href,state.id));return;}
 if(action==='export-draft'){download(state.form,state.id);return;}
 if(action==='preview-draft'){persist();state.tab='overview';state.quantity='1';setHash(`#/project/${state.id}`);return;}
 if(action==='participate'){participation();return;}
 if(action==='copy-participation'){await copy($('participation-brief').value);return;}
 if(action==='minus'||action==='plus'){const result=projectFor(route()[1]);if(!result)return;const cap=Math.min(Number(result.f.maxTx),Number(result.f.limit)),current=Number(state.quantity)||1;state.quantity=String(action==='minus'?Math.max(1,current-1):Math.min(cap,current+1));$('quote-quantity').value=state.quantity;updateQuote();return;}
 if(action==='export-project'){const result=projectFor(route()[1]);if(result)download(result.f,result.p.id);return;}
 if(action==='import'){openImport();return;}
 if(action==='confirm-import'){try{const form=importManifest($('import-json').value);state.form=form;state.id=uid();state.step=3;state.confirmed=false;state.errors={};persist();dialog.close();setHash('#/create');toast(t('导入成功。请重新审阅规则。','Imported. Review the launch terms again.'));}catch(error){$('import-error').textContent=error.message==='size'?t('文件超过 512 KB，请缩小封面或方案文件。','File exceeds 512 KB. Reduce the cover or draft size.'):error.message==='schema'?t('格式不符，请使用 ECHO Launch 导出的方案 JSON。','Format mismatch. Use an ECHO Launch draft JSON.'):error.message==='validation'?t('参数不完整或无效。请检查必填项、价格、额度和链接。','Incomplete or invalid parameters. Check required fields, price, caps and links.'):t('JSON 无法解析。请检查文件是否完整。','Could not parse JSON. Check that the file is complete.');}return;}
 if(action==='delete-confirm'){const next=drafts.filter(d=>d.id!==el.dataset.id);try{localStorage.setItem(KEY,JSON.stringify(next));drafts=next;if(state.id===el.dataset.id){state.id=null;state.form={...DEFAULT_FORM};state.step=1;}dialog.close();render();toast(t('本地草稿已删除。','Local draft deleted.'));}catch{toast(t('未能删除，请先下载备份。','Could not delete. Download a backup first.'),true);}return;}
});

app.addEventListener('keydown',event=>{
 if(!event.target.matches('[role="tab"][data-tab]'))return;
 const tabs=['overview','rules','participation','agent'],index=tabs.indexOf(state.tab);let next;
 if(event.key==='ArrowRight')next=tabs[(index+1)%tabs.length];else if(event.key==='ArrowLeft')next=tabs[(index+tabs.length-1)%tabs.length];else if(event.key==='Home')next=tabs[0];else if(event.key==='End')next=tabs.at(-1);else return;
 event.preventDefault();state.tab=next;render();$(`detail-tab-${next}`)?.focus({preventScroll:true});
});

dialog.addEventListener('change',async event=>{if(event.target.id!=='import-file')return;const file=event.target.files?.[0];if(!file)return;if(file.size>MAX_MANIFEST_LENGTH){$('import-error').textContent=t('文件超过 512 KB。','File exceeds 512 KB.');return;}try{$('import-json').value=await file.text();$('import-error').textContent='';}catch{$('import-error').textContent=t('无法读取文件，请重新选择。','Could not read the file. Choose it again.');}});

let coverRequest=0;
app.addEventListener('change',async event=>{
 if(event.target.id!=='cover-file')return;const file=event.target.files?.[0];if(!file)return;
 const request=++coverRequest,form=state.form,status=$('cover-status');status.classList.remove('error');status.textContent=t('正在生成本地封面预览…','Preparing the local cover preview…');
 try{const image=await createLocalCover(file);if(request!==coverRequest||form!==state.form||route()[0]!=='create')return;state.form.cover=image;state.confirmed=false;delete state.errors.cover;const saved=persist();render();toast(saved?t('封面已保存在本地草稿。','Cover saved in the local draft.'):t('封面已预览，浏览器未能保存，请导出 JSON。','Cover previewed but not saved. Export JSON.'),!saved);}catch(error){if(request!==coverRequest||form!==state.form)return;status.classList.add('error');status.textContent=error.message==='image-type'?t('请选择 JPG、PNG 或 WebP 图片。','Choose a JPG, PNG or WebP image.'):error.message==='image-size'?t('请选择不超过 2 MB 的图片。','Choose an image up to 2 MB.'):t('无法读取这张图片，请换一张。','Could not read this image. Choose another.');event.target.value='';}
});

document.addEventListener('error',event=>{if(!event.target.matches?.('.project-cover-image'))return;event.target.hidden=true;const message=event.target.parentElement.querySelector('.cover-image-error');if(message)message.hidden=false;},true);
window.addEventListener('hashchange',()=>{state.tab='overview';state.quantity='1';render();finishNavigation();});
if(!location.hash)history.replaceState(null,'','#/projects');render();
